<script>
(function(){
  var menu=document.getElementById('side-menu'),ov=document.getElementById('side-overlay');
  function open(){menu.classList.add('open');ov.classList.add('show');document.body.style.overflow='hidden'}
  function close(){menu.classList.remove('open');ov.classList.remove('show');document.body.style.overflow=''}
  var o=document.querySelector('[data-open-side]'),c=document.querySelector('[data-close-side]');if(o)o.addEventListener('click',open);if(c)c.addEventListener('click',close);if(ov)ov.addEventListener('click',close);
  var search=document.getElementById('side-nav-search'),empty=document.getElementById('side-nav-empty');
  if(search){search.addEventListener('input',function(){var q=this.value.trim().toLowerCase(),visible=0;document.querySelectorAll('.side .nav-link,.side .nav-home').forEach(function(a){var hit=!q||a.textContent.toLowerCase().includes(q);a.style.display=hit?'flex':'none';if(hit)visible++});document.querySelectorAll('.side .nav-group').forEach(function(g){var links=[].slice.call(g.querySelectorAll('.nav-link'));var show=!q||links.some(function(a){return a.style.display!=='none'})||g.querySelector('summary').textContent.toLowerCase().includes(q);g.style.display=show?'block':'none';if(q&&show)g.open=true});empty.style.display=visible?'none':'block'});}
})();
</script>
